// Cada caso corre en las dos arquitecturas: A/B con los mismos datos.
const ARQ = [
  { arquitectura: 'A (openai/gpt-oss-20b)', modelo: 'openai/gpt-oss-20b' },
  { arquitectura: 'B (openai/gpt-oss-120b)', modelo: 'openai/gpt-oss-120b' },
];
return ARQ.flatMap(a => $input.all().map(i => ({ json: { ...i.json, ...a } })));

