// Junta cada respuesta con su caso y guarda los tokens que informó Groq.
const casos = $('Duplicar para A y B').all();
return $input.all().map((item, i) => ({ json: {
  ...casos[i].json,
  respuesta: item.json.choices[0].message.content.trim(),
  tokens_entrada: item.json.usage.prompt_tokens,
  tokens_salida: item.json.usage.completion_tokens,
  segundos: item.json.usage.total_time || 0,
} }));

// La IA extrae (afirmaciones y fragmentos útiles); el código cuenta. Así se calculan las métricas de RAGAS.
const PRECIOS = {"openai/gpt-oss-20b": [0.075, 0.3], "openai/gpt-oss-120b": [0.15, 0.6]};
const JUEZ = 'openai/gpt-oss-120b';
const base = $('Guardar la respuesta').all();
return $input.all().map((item, i) => {
  const b = base[i].json;
  const j = JSON.parse(item.json.choices[0].message.content);
  const u = item.json.usage;
  // Fidelidad (faithfulness): afirmaciones sustentadas en el contexto / afirmaciones de la respuesta
  const af = j.afirmaciones;
  const fidelidad = af.length ? af.filter(a => a.sustentada).length / af.length : 1;
  // Precisión del contexto (context precision): ¿los fragmentos útiles llegaron primero?
  let relevantes = 0, suma = 0;
  j.fragmentos.forEach((f, k) => { if (f.util) { relevantes++; suma += relevantes / (k + 1); } });
  const precision_contexto = relevantes ? suma / relevantes : 0;
  // Recall del contexto (context recall): afirmaciones de la referencia que estaban en el contexto
  const ref = j.referencia;
  const recall_contexto = ref.length ? ref.filter(r => r.en_contexto).length / ref.length : 1;
  // Correcta: la decide el código con los datos clave del caso de oro (la verdad), no el juez
  const correcta = b.debe.every(p => new RegExp(p, 'i').test(b.respuesta))
               && !b.no_debe.some(p => new RegExp(p, 'i').test(b.respuesta));
  // Costo real: tokens que informa Groq (incluye los de razonamiento) x precio por millón
  const pa = PRECIOS[b.modelo], pj = PRECIOS[JUEZ];
  const costo = (b.tokens_entrada * pa[0] + b.tokens_salida * pa[1]
               + u.prompt_tokens * pj[0] + u.completion_tokens * pj[1]) / 1e6;
  return { json: {
    arquitectura: b.arquitectura, caso: b.caso, pregunta: b.pregunta, respuesta: b.respuesta,
    fidelidad: +fidelidad.toFixed(2),
    relevancia: +(j.relevancia / 5).toFixed(2),
    precision_contexto: +precision_contexto.toFixed(2),
    recall_contexto: +recall_contexto.toFixed(2),
    correcta,
    veredicto: j.veredicto,
    juez_acierta: (j.veredicto === 'ACEPTADO') === correcta,
    hitl: j.veredicto !== 'ACEPTADO',
    errores: j.errores.join(' | '),
    tokens_agente: b.tokens_entrada + b.tokens_salida,
    tokens_juez: u.prompt_tokens + u.completion_tokens,
    costo_usd: +costo.toFixed(6),
    segundos: +(b.segundos + (u.total_time || 0)).toFixed(2),
  } };
});

// Supuestos del negocio (caso.md). Cambialos por los de tu cliente.
const S = {
  "consultas_por_dia": 60,
  "porcentaje_repetidas": 0.7,
  "dias_habiles_mes": 22,
  "horas_julian_por_dia": 3,
  "costo_hora_julian_usd": 6,
  "n8n_por_mes_usd": 24,
  "implementacion_usd": 1500
};
const consultas_mes = Math.round(S.consultas_por_dia * S.porcentaje_repetidas * S.dias_habiles_mes);
const filas = $input.all().map(i => i.json);
const prom = (xs, k) => xs.reduce((a, x) => a + Number(x[k]), 0) / xs.length;
const pct = x => Math.round(x * 100) + '%';
return ['A', 'B'].map(arq => {
  const xs = filas.filter(f => f.arquitectura.startsWith(arq));
  const hitl = xs.filter(f => f.hitl).length / xs.length;
  const costo = prom(xs, 'costo_usd');
  // Ahorro: las horas de Julián en consultas repetidas, menos las que igual pasan por una persona (HITL)
  const ahorro_mes = S.horas_julian_por_dia * S.dias_habiles_mes * S.costo_hora_julian_usd * (1 - hitl);
  const costo_ia_mes = consultas_mes * costo;
  const neto_mes = ahorro_mes - costo_ia_mes - S.n8n_por_mes_usd;
  return { json: {
    arquitectura: xs[0].arquitectura,
    corridas: xs.length,
    precision: pct(xs.filter(f => f.correcta).length / xs.length),
    fidelidad: +prom(xs, 'fidelidad').toFixed(2),
    relevancia: +prom(xs, 'relevancia').toFixed(2),
    precision_contexto: +prom(xs, 'precision_contexto').toFixed(2),
    recall_contexto: +prom(xs, 'recall_contexto').toFixed(2),
    hitl_rate: pct(hitl),
    acuerdo_juez_verdad: pct(xs.filter(f => f.juez_acierta).length / xs.length),
    tokens_promedio: Math.round(prom(xs, 'tokens_agente') + prom(xs, 'tokens_juez')),
    costo_por_ejecucion_usd: +costo.toFixed(5),
    costo_1000_ejecuciones_usd: +(costo * 1000).toFixed(2),
    segundos_promedio: +prom(xs, 'segundos').toFixed(2),
    consultas_mes,
    ahorro_mes_usd: Math.round(ahorro_mes),
    costo_total_mes_usd: +(costo_ia_mes + S.n8n_por_mes_usd).toFixed(2),
    neto_mes_usd: Math.round(neto_mes),
    payback_meses: neto_mes > 0 ? +(S.implementacion_usd / neto_mes).toFixed(1) : 'no se paga',
    roi_12_meses: pct((neto_mes * 12 - S.implementacion_usd) / S.implementacion_usd),
  } };
});
